import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';
import '../../../services/tv/auren_tv_service.dart';
class AurenTvScreen extends StatefulWidget { const AurenTvScreen({super.key}); @override State<AurenTvScreen> createState()=>_State(); }
class _State extends State<AurenTvScreen>{ String country='',category=''; VideoPlayerController? player;
 @override void dispose(){player?.dispose();super.dispose();}
 Future<void> play(AurenTvChannel c) async {await player?.dispose(); final p=VideoPlayerController.networkUrl(Uri.parse(c.url)); setState(()=>player=p); try{await p.initialize();await p.play();if(mounted)setState((){});}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذر تشغيل القناة؛ قد تكون غير متاحة أو محجوبة جغرافياً.')));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('AUREN TV • World')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(decoration:const InputDecoration(labelText:'Country / البلد'),onChanged:(v)=>country=v)),const SizedBox(width:8),Expanded(child:TextField(decoration:const InputDecoration(labelText:'Category / الفئة'),onChanged:(v)=>category=v)),IconButton(onPressed:()=>setState((){}),icon:const Icon(Icons.search))])),if(player?.value.isInitialized==true)AspectRatio(aspectRatio:player!.value.aspectRatio,child:VideoPlayer(player!)),Expanded(child:FutureBuilder<List<AurenTvChannel>>(future:AurenTvService.instance.load(country:country,category:category),builder:(context,s){if(s.hasError)return Center(child:Text('تعذر تحميل القنوات: '+s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());final xs=s.data!;return ListView.separated(padding:const EdgeInsets.all(12),itemCount:xs.length,separatorBuilder:(_,__)=>const SizedBox(height:6),itemBuilder:(_,i){final c=xs[i];return Card(child:ListTile(leading:c.logo.isEmpty?const CircleAvatar(child:Icon(Icons.tv)):CircleAvatar(backgroundImage:NetworkImage(c.logo)),title:Text(c.name),subtitle:Text(c.country+' • '+c.language+' • '+c.category),trailing:const Icon(Icons.play_circle_fill),onTap:()=>play(c)));});}))]));
}